:root { --bg: #faf7f2; --surface: #ffffff; --ink: #2b2620; --muted: #7a7166; --line: #e7e0d5; --accent: #b5532f; --accent-ink: #ffffff; --soft: #f2ece3; --ok: #3f6b4a; --radius: 10px; font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif; color: var(--ink); background: var(--bg); }* { box-sizing: border-box; }body { margin: 0px; background: var(--bg); }a { color: inherit; }h1, h2, h3 { font-family: Georgia, "Times New Roman", serif; font-weight: 500; }.muted { color: var(--muted); }.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); }.header { background: var(--surface); border-bottom: 1px solid var(--line); position: sticky; top: 0px; z-index: 20; }.header-inner { max-width: 1120px; margin: 0px auto; padding: 14px 20px; display: flex; align-items: center; gap: 24px; }.logo { font-family: Georgia, serif; font-size: 22px; text-decoration: none; white-space: nowrap; }.logo span { color: var(--accent); }.cart-link { margin-left: auto; text-decoration: none; display: inline-flex; align-items: center; gap: 8px; font-weight: 600; }.cart-count { background: var(--ink); color: rgb(255, 255, 255); border-radius: 999px; min-width: 22px; height: 22px; display: inline-grid; place-items: center; font-size: 12px; padding: 0px 6px; }.cats { max-width: 1120px; margin: 0px auto; padding: 0px 20px 10px; display: flex; gap: 18px; font-size: 14px; }.cats a { text-decoration: none; color: var(--muted); padding-bottom: 4px; border-bottom: 2px solid transparent; }.cats a.active { color: var(--ink); border-color: var(--accent); }.search { position: relative; flex: 1 1 0%; max-width: 460px; }.search input { width: 100%; padding: 10px 14px; border: 1px solid var(--line); border-radius: 999px; background: var(--soft); font: inherit; }.search input:focus { outline: 2px solid var(--accent); background: rgb(255, 255, 255); }.suggestions { position: absolute; top: calc(100% + 6px); left: 0px; right: 0px; margin: 0px; padding: 6px; list-style: none; background: rgb(255, 255, 255); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: rgba(0, 0, 0, 0.08) 0px 12px 30px; z-index: 30; }.suggestions li { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 6px; cursor: pointer; }.suggestions li:hover, .suggestions li.active { background: var(--soft); }.suggestion-empty { color: var(--muted); cursor: default !important; }.swatch { width: 18px; height: 18px; border-radius: 4px; flex: 0 0 auto; }.s-name { flex: 1 1 0%; }.s-price { color: var(--muted); font-size: 14px; }.page { max-width: 1120px; margin: 0px auto; padding: 24px 20px 64px; min-height: 70vh; }.footer { border-top: 1px solid var(--line); padding: 24px 20px; display: flex; justify-content: space-between; max-width: 1120px; margin: 0px auto; color: var(--muted); font-size: 14px; }.hero { background: linear-gradient(120deg, rgb(239, 226, 207), rgb(230, 211, 192) 60%, rgb(217, 193, 168)); border-radius: 16px; padding: 48px 40px; margin-bottom: 28px; }.hero h1 { font-size: 40px; margin: 6px 0px 12px; max-width: 560px; }.eyebrow { text-transform: uppercase; letter-spacing: 0.12em; font-size: 12px; color: var(--accent); margin: 0px; }.toolbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }.toolbar h2 { margin: 0px; }.sort { font-size: 14px; color: var(--muted); display: flex; gap: 8px; align-items: center; }select, .promo input, .checkout-form input:not([type="radio"]) { font: inherit; padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; background: rgb(255, 255, 255); }.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 20px; }.card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; display: flex; flex-direction: column; }.card.skeleton { height: 330px; background: linear-gradient(90deg, rgb(243, 238, 230), rgb(235, 228, 217), rgb(243, 238, 230)); }.card-link { text-decoration: none; flex: 1 1 0%; }.card-body { padding: 12px 14px 4px; }.card-body h3 { margin: 4px 0px 6px; font-size: 18px; }.card-cat { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; }.card-price { font-weight: 600; }.card-add { margin: 12px 14px 14px; }.pimg { background: radial-gradient(circle at 30% 25%, rgba(255,255,255,0.45), transparent 55%), var(--tone); display: grid; place-items: center; color: rgba(255, 255, 255, 0.85); font-family: Georgia, serif; }.pimg-md { aspect-ratio: 4 / 3; font-size: 40px; }.pimg-lg { aspect-ratio: 1 / 1; border-radius: 16px; font-size: 96px; }.pimg-sm { width: 72px; height: 72px; border-radius: 8px; font-size: 22px; flex: 0 0 auto; }.btn { font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-weight: 600; border-radius: 8px; padding: 10px 18px; cursor: pointer; border: 1px solid transparent; text-decoration: none; display: inline-block; text-align: center; }.btn-primary { background: var(--accent); color: var(--accent-ink); }.btn-primary:hover { background: rgb(156, 68, 37); }.btn-primary:disabled { opacity: 0.6; cursor: default; }.btn-secondary { background: rgb(255, 255, 255); border-color: var(--ink); color: var(--ink); }.btn-secondary:hover { background: var(--soft); }.btn-secondary:disabled { opacity: 0.5; cursor: default; }.btn-block { width: 100%; padding: 14px; font-size: 16px; }.link-btn { background: none; border: none; padding: 0px 2px; height: 32px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-size: 14px; color: var(--muted); text-decoration: underline; cursor: pointer; text-align: right; }.link-btn:hover { color: var(--ink); }.crumbs { font-size: 14px; color: var(--muted); margin-bottom: 18px; }.crumbs a { text-decoration: none; }.product { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; margin-bottom: 48px; }.product h1 { font-size: 36px; margin: 0px 0px 8px; }.product-price { font-size: 22px; font-weight: 600; }.product-desc { line-height: 1.6; color: rgb(75, 68, 60); }.buy-row { display: flex; gap: 14px; align-items: end; margin: 24px 0px; }.buy-row label { display: flex; flex-direction: column; font-size: 13px; color: var(--muted); gap: 4px; }.perks { color: var(--muted); font-size: 14px; padding-left: 18px; line-height: 1.8; }.skeleton-block { height: 420px; background: rgb(241, 235, 226); border-radius: 16px; }.section-title { font-size: 20px; margin: 0px 0px 14px; }.empty { padding: 40px 0px; color: var(--muted); }.page-title { margin: 0px 0px 18px; font-size: 32px; }.cart-page, .checkout { display: grid; grid-template-columns: 1fr 340px; gap: 32px; align-items: start; }.cart-items { display: flex; flex-direction: column; gap: 12px; }.offer { height: 44px; display: flex; align-items: center; padding: 0px 16px; border-radius: 8px; background: rgb(244, 227, 211); color: rgb(122, 59, 32); font-size: 14px; }.line { display: grid; grid-template-columns: 72px 1fr 80px 90px 120px; align-items: center; gap: 16px; padding: 14px; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); }.line-saved { grid-template-columns: 72px 1fr auto; margin-bottom: 10px; }.line-info { display: flex; flex-direction: column; gap: 4px; }.line-info a { font-weight: 600; text-decoration: none; }.line-total { font-weight: 600; text-align: right; }.line-actions { display: flex; flex-direction: column; align-items: flex-end; gap: 24px; }.saved { margin-top: 36px; }.summary { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px; position: sticky; top: 130px; }.summary h2 { margin: 0px 0px 14px; font-size: 22px; }.row { display: flex; justify-content: space-between; padding: 8px 0px; }.row.total { border-top: 1px solid var(--line); margin-top: 6px; padding-top: 12px; font-weight: 700; font-size: 18px; }.row.discount { color: var(--ok); }.summary .btn-block { margin-top: 14px; }.sum-line { display: grid; grid-template-columns: 1fr 64px 80px; gap: 8px; align-items: center; padding: 6px 0px; font-size: 14px; }.sum-line span:last-child { text-align: right; }.promo { display: flex; gap: 8px; margin: 14px 0px 6px; }.promo input { flex: 1 1 0%; min-width: 0px; }.error { color: rgb(179, 38, 30); font-size: 14px; margin: 4px 0px; }.checkout-form fieldset { border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); padding: 18px 20px; margin: 0px 0px 18px; display: flex; flex-direction: column; gap: 12px; }.checkout-form legend { font-weight: 600; padding: 0px 6px; }.checkout-form label { display: flex; flex-direction: column; gap: 4px; font-size: 14px; color: var(--muted); }.checkout-form label.radio { flex-direction: row; align-items: center; gap: 10px; color: var(--ink); }.two { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }.fine { font-size: 13px; color: var(--muted); text-align: center; }.combo { position: relative; margin-top: -8px; }.combo-input { width: 100%; color: var(--ink); padding-right: 36px !important; }.combo-toggle { position: absolute; right: 4px; top: 4px; bottom: 4px; width: 30px; border: none; background: transparent; cursor: pointer; color: var(--muted); }.combo-list { position: absolute; top: calc(100% + 4px); left: 0px; right: 0px; margin: 0px; padding: 4px; list-style: none; background: rgb(255, 255, 255); border: 1px solid var(--line); border-radius: 8px; box-shadow: rgba(0, 0, 0, 0.08) 0px 12px 30px; max-height: 240px; overflow: auto; z-index: 10; }.combo-list li { padding: 8px 10px; border-radius: 6px; cursor: pointer; }.combo-list li.active { background: var(--soft); }.combo-list li[aria-selected="true"] { font-weight: 600; }.combo-empty { color: var(--muted); }.toast { position: fixed; right: 24px; bottom: 24px; background: var(--ink); color: rgb(255, 255, 255); padding: 14px 18px; border-radius: 10px; display: flex; gap: 16px; align-items: center; box-shadow: rgba(0, 0, 0, 0.2) 0px 10px 30px; z-index: 50; }.toast a { color: rgb(244, 201, 168); font-weight: 600; }.confirm { max-width: 760px; }.confirm h1 { font-size: 36px; margin: 6px 0px; }.confirm-grid { display: grid; grid-template-columns: 1.4fr 1fr; gap: 32px; margin: 28px 0px; }address { font-style: normal; line-height: 1.6; }@media (max-width: 820px) {
  .cart-page, .checkout, .product, .confirm-grid { grid-template-columns: 1fr; }
  .line { grid-template-columns: 56px 1fr 70px; }
  .line-total { display: none; }
  .line-actions { grid-column: 2 / -1; flex-direction: row; justify-content: flex-end; }
}
